use crate::error::CliError;

pub const USAGE: &str = "\
Usage: tabulate [OPTIONS] < input

Aligns delimited text from stdin into a plain-text table.

Options:
  -d, --delimiter <CHAR>   Cell delimiter, or `tab` (default: ,)
  -H, --header             Underline the first row
  -b, --border             Draw `|` between the columns
  -w, --max-width <N>      Cut cells longer than N characters
  -c, --compact            Deprecated: print rows without padding
  -h, --help               Show this help
";

#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Options {
    pub delimiter: char,
    pub header: bool,
    pub border: bool,
    pub compact: bool,
    pub max_width: Option<usize>,
}

impl Default for Options {
    fn default() -> Self {
        Options {
            delimiter: ',',
            header: false,
            border: false,
            compact: false,
            max_width: None,
        }
    }
}

#[derive(Debug, PartialEq, Eq)]
pub enum Command {
    Help,
    Render(Options),
}

pub fn parse_args(args: &[&str]) -> Result<Command, CliError> {
    let mut options = Options::default();
    let mut args = args.iter().copied();
    while let Some(arg) = args.next() {
        match arg {
            "-h" | "--help" => return Ok(Command::Help),
            "-H" | "--header" => options.header = true,
            "-b" | "--border" => options.border = true,
            "-c" | "--compact" => {
                eprintln!("warning: --compact is deprecated and will be removed in 1.0; use --max-width instead");
                options.compact = true;
            }
            "-d" | "--delimiter" => options.delimiter = parse_delimiter(arg, args.next())?,
            "-w" | "--max-width" => options.max_width = Some(parse_width(arg, args.next())?),
            other => return Err(CliError::UnknownOption(other.to_string())),
        }
    }
    Ok(Command::Render(options))
}

fn parse_delimiter(option: &str, value: Option<&str>) -> Result<char, CliError> {
    let value = value.ok_or_else(|| CliError::MissingValue(option.to_string()))?;
    if value == "tab" {
        return Ok('\t');
    }
    let mut chars = value.chars();
    match (chars.next(), chars.next()) {
        (Some(delimiter), None) => Ok(delimiter),
        _ => Err(invalid_value(option, value)),
    }
}

fn parse_width(option: &str, value: Option<&str>) -> Result<usize, CliError> {
    let value = value.ok_or_else(|| CliError::MissingValue(option.to_string()))?;
    match value.parse::<usize>() {
        Ok(width) if width > 0 => Ok(width),
        _ => Err(invalid_value(option, value)),
    }
}

fn invalid_value(option: &str, value: &str) -> CliError {
    CliError::InvalidValue {
        option: option.to_string(),
        value: value.to_string(),
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn options(args: &[&str]) -> Options {
        match parse_args(args) {
            Ok(Command::Render(options)) => options,
            other => panic!("expected options, got {other:?}"),
        }
    }

    #[test]
    fn defaults_apply_without_arguments() {
        assert_eq!(options(&[]), Options::default());
    }

    #[test]
    fn parses_short_and_long_flags() {
        assert!(options(&["-H"]).header);
        assert!(options(&["--border"]).border);
    }

    #[test]
    fn parses_option_values() {
        let parsed = options(&["-d", "tab", "--max-width", "8"]);
        assert_eq!(parsed.delimiter, '\t');
        assert_eq!(parsed.max_width, Some(8));
    }

    #[test]
    fn compact_flag_sets_compact() {
        assert!(options(&["--compact"]).compact);
        assert!(options(&["-c"]).compact);
    }

    #[test]
    fn rejects_unknown_options() {
        assert_eq!(
            parse_args(&["--nope"]),
            Err(CliError::UnknownOption("--nope".to_string()))
        );
    }

    #[test]
    fn rejects_a_missing_value() {
        assert_eq!(
            parse_args(&["--delimiter"]),
            Err(CliError::MissingValue("--delimiter".to_string()))
        );
    }

    #[test]
    fn rejects_a_zero_width() {
        assert!(parse_args(&["-w", "0"]).is_err());
    }
}
use crate::cli::Options;

const GAP: &str = "  ";

pub fn render_table(rows: &[Vec<String>], options: &Options) -> String {
    let rows = limit_widths(rows, options.max_width);
    if options.compact {
        return render_compact(&rows);
    }
    let widths = column_widths(&rows);
    let mut lines = Vec::new();
    for (index, row) in rows.iter().enumerate() {
        lines.push(render_row(row, &widths, options.border));
        if index == 0 && options.header {
            lines.push(render_rule(&widths, options.border));
        }
    }
    join_lines(&lines)
}

fn limit_widths(rows: &[Vec<String>], max_width: Option<usize>) -> Vec<Vec<String>> {
    match max_width {
        None => rows.to_vec(),
        Some(max) => rows
            .iter()
            .map(|row| row.iter().map(|cell| truncate_cell(cell, max)).collect())
            .collect(),
    }
}

fn truncate_cell(cell: &str, max: usize) -> String {
    if cell.chars().count() <= max {
        return cell.to_string();
    }
    let kept: String = cell.chars().take(max.saturating_sub(1)).collect();
    format!("{kept}…")
}

fn column_widths(rows: &[Vec<String>]) -> Vec<usize> {
    let columns = rows.iter().map(Vec::len).max().unwrap_or(0);
    (0..columns)
        .map(|column| {
            rows.iter()
                .filter_map(|row| row.get(column))
                .map(|cell| cell.chars().count())
                .max()
                .unwrap_or(0)
        })
        .collect()
}

fn pad_cell(cell: &str, width: usize) -> String {
    format!("{cell:<width$}")
}

fn render_row(row: &[String], widths: &[usize], border: bool) -> String {
    let cells: Vec<String> = widths
        .iter()
        .enumerate()
        .map(|(column, &width)| pad_cell(row.get(column).map_or("", String::as_str), width))
        .collect();
    let line = if border {
        format!("| {} |", cells.join(" | "))
    } else {
        cells.join(GAP)
    };
    line.trim_end().to_string()
}

fn render_rule(widths: &[usize], border: bool) -> String {
    let dashes: Vec<String> = widths.iter().map(|&width| "-".repeat(width)).collect();
    if border {
        format!("|-{}-|", dashes.join("-+-"))
    } else {
        dashes.join(GAP)
    }
}

fn render_compact(rows: &[Vec<String>]) -> String {
    let lines: Vec<String> = rows.iter().map(|row| trim_cells(row).join(" ")).collect();
    join_lines(&lines)
}

fn trim_cells(row: &[String]) -> Vec<&str> {
    row.iter().map(|cell| cell.trim()).collect()
}

fn join_lines(lines: &[String]) -> String {
    lines.iter().map(|line| format!("{line}\n")).collect()
}

#[cfg(test)]
mod tests {
    use super::*;

    fn rows(lines: &[&[&str]]) -> Vec<Vec<String>> {
        lines
            .iter()
            .map(|line| line.iter().map(|cell| cell.to_string()).collect())
            .collect()
    }

    #[test]
    fn aligns_columns_to_the_widest_cell() {
        let table = rows(&[&["id", "name"], &["10", "Ann"]]);
        assert_eq!(
            render_table(&table, &Options::default()),
            "id  name\n10  Ann\n"
        );
    }

    #[test]
    fn border_wraps_the_cells() {
        let table = rows(&[&["a", "bb"]]);
        let options = Options { border: true, ..Options::default() };
        assert_eq!(render_table(&table, &options), "| a | bb |\n");
    }

    #[test]
    fn header_is_underlined() {
        let table = rows(&[&["id", "name"], &["10", "Ann"]]);
        let options = Options { header: true, ..Options::default() };
        assert_eq!(
            render_table(&table, &options),
            "id  name\n--  ----\n10  Ann\n"
        );
    }

    #[test]
    fn long_cells_are_cut_to_the_max_width() {
        let table = rows(&[&["abcdef"]]);
        let options = Options { max_width: Some(4), ..Options::default() };
        assert_eq!(render_table(&table, &options), "abc…\n");
    }

    #[test]
    fn compact_joins_cells_with_one_space() {
        let table = rows(&[&["id", "name"], &["10", "Ann"]]);
        let options = Options { compact: true, ..Options::default() };
        assert_eq!(render_table(&table, &options), "id name\n10 Ann\n");
    }

    #[test]
    fn compact_trims_cells() {
        let table = rows(&[&["  a ", " b"]]);
        let options = Options { compact: true, ..Options::default() };
        assert_eq!(render_table(&table, &options), "a b\n");
    }
}
use tabulate::{run, CliError};

const PEOPLE: &str = "id,name,city\n7,Ann,Oslo\n10,Bob,Rome\n";

#[test]
fn default_output_is_aligned() {
    assert_eq!(
        run(&[], PEOPLE).unwrap(),
        "id  name  city\n7   Ann   Oslo\n10  Bob   Rome\n"
    );
}

#[test]
fn header_is_underlined() {
    assert_eq!(
        run(&["--header"], PEOPLE).unwrap(),
        "id  name  city\n--  ----  ----\n7   Ann   Oslo\n10  Bob   Rome\n"
    );
}

#[test]
fn border_draws_pipes() {
    assert_eq!(
        run(&["-b", "-H"], "a,b\nccc,d\n").unwrap(),
        "| a   | b |\n|-----+---|\n| ccc | d |\n"
    );
}

#[test]
fn custom_delimiter_splits_cells() {
    assert_eq!(run(&["-d", ";"], "a;bb\nc;d\n").unwrap(), "a  bb\nc  d\n");
}

#[test]
fn tab_delimiter_is_spelled_out() {
    assert_eq!(run(&["-d", "tab"], "a\tbb\n").unwrap(), "a  bb\n");
}

#[test]
fn max_width_truncates_long_cells() {
    assert_eq!(run(&["-w", "3"], "abcdef,x\n").unwrap(), "ab…  x\n");
}

#[test]
fn ragged_rows_are_padded() {
    assert_eq!(run(&[], "a,b,c\nd\n").unwrap(), "a  b  c\nd\n");
}

#[test]
fn empty_input_prints_nothing() {
    assert_eq!(run(&[], "").unwrap(), "");
}

#[test]
fn unknown_option_is_rejected() {
    assert_eq!(
        run(&["--nope"], PEOPLE),
        Err(CliError::UnknownOption("--nope".to_string()))
    );
}

#[test]
fn missing_value_is_reported() {
    assert_eq!(
        run(&["-w"], PEOPLE),
        Err(CliError::MissingValue("-w".to_string()))
    );
}

#[test]
fn help_lists_every_option() {
    let help = run(&["--help"], "").unwrap();
    for option in ["--delimiter", "--header", "--border", "--max-width", "--help"] {
        assert!(help.contains(option), "help does not mention {option}");
    }
}

#[test]
fn compact_flag_prints_single_spaced_rows() {
    assert_eq!(
        run(&["--compact"], PEOPLE).unwrap(),
        "id name city\n7 Ann Oslo\n10 Bob Rome\n"
    );
}

#[test]
fn short_compact_flag_is_accepted() {
    assert_eq!(run(&["-c"], "a , b\n").unwrap(), "a b\n");
}

#[test]
fn compact_ignores_border_and_header() {
    assert_eq!(run(&["-c", "-b", "-H"], "a,b\n").unwrap(), "a b\n");
}
